#!/usr/bin/env -S bun --no-env-file
// Writes each text that a plugin ships from its source in `src/` (design D12, `just generate`).
//
//   bun tools/generate.ts           write each generated file
//   bun tools/generate.ts --check   exit 1 and name each generated file that differs from its source
//
// `src/` has the layout of the repository: `src/plugins/<name>/agents/x.md` gives `plugins/<name>/agents/x.md`.
// `src/shared/` holds the parts that more than one file repeats, and gives no file of its own.
// In a source, a line `{{include NAME}}` gives the text of `src/shared/NAME.md`, `{{include NAME.json}}` the text of `src/shared/NAME.json`, and `{{NAME}}` the value of the limit `NAME` of `VALUES`.
// A `hooks.json` also gets its texts from the files next to it: `description.txt` and `<Event>.prompt.txt`.
// A folder `NAME.ts/` gives the module `NAME.ts`, with one constant for each `.md` or `.json` file in it, so that code can import the texts.
// The constant of `doing-tasks.md` is `DOING_TASKS`, a `.json` file gives an object, and the module holds no logic.
// Biome formats each generated module, so the lint of `plugins/` passes on it.
// Each generated file starts with a header that names its source, except a JSON file, because JSON has no comment.

import fs from "node:fs";
import path from "node:path";
import { FILE_MAX_BYTES } from "../plugins/dotclaude/features/adherence/limits.ts";
import {
  HAIKU_CONTEXT_MAX,
  REPORT_MAX_WORDS,
  SUBAGENT_CONTEXT_MAX,
  TURNS_LEFT_AT,
} from "../plugins/dotclaude/features/context/limits.ts";
import { MAX_ROWS } from "../plugins/dotclaude/features/statusline/limits.ts";
import {
  BASH_OUTPUT_MAX_CHARS,
  CONTEXT_WINDOW,
  POLICY_FILE_MAX_CHARS,
  POLICY_TIMEOUT_MS,
  USAGE_LEVELS,
} from "../plugins/dotclaude/lib/budget.ts";

const REPO = path.resolve(import.meta.dir, "..");

/** The limits that a source can name as `{{NAME}}`, from the one place in code where each is set. A number has the `300,000` form of the docs. */
export const VALUES: Record<string, string> = Object.fromEntries(
  Object.entries({
    BASH_OUTPUT_MAX_CHARS,
    CONTEXT_WINDOW,
    FILE_MAX_BYTES,
    HAIKU_CONTEXT_MAX,
    MAX_ROWS,
    POLICY_FILE_MAX_CHARS,
    POLICY_TIMEOUT_MS,
    REPORT_MAX_WORDS,
    SUBAGENT_CONTEXT_MAX,
    TURNS_LEFT_AT,
    USAGE_LEVEL_LOW: USAGE_LEVELS[0],
    USAGE_LEVEL_HIGH: USAGE_LEVELS[1],
  }).map(([name, value]) => [name, value.toLocaleString("en-US")]),
);

const PROMPT_FILE = /^([A-Za-z]+)\.prompt\.txt$/;
const INCLUDE = /^\{\{include ([a-z0-9-]+(?:\.json)?)\}\}$/gm;
const VALUE = /\{\{([A-Z0-9_]+)\}\}/g;

/** The words of the header, which a test and the size bound find in the first lines of a generated file. */
export const GENERATED_MARK = "Generated by `just generate` from";

/** True when the first lines of `text` hold the header of a generated file. */
export const isGenerated = (text: string): boolean =>
  text.split("\n", 3).some((line) => line.includes(GENERATED_MARK));

/** One generated file: its path and the path of its source, both relative to the root, and its text. */
export type Output = { file: string; source: string; text: string };

/** The parts of a `hooks.json` file that the generator reads and writes. */
export type HooksFile = {
  description?: string;
  hooks?: Record<string, { hooks: { type: string; prompt?: string }[] }[]>;
  [key: string]: unknown;
};

/** `p` in the `/` form that the repository paths of this tool use. */
const posix = (p: string) => p.split(path.sep).join(path.posix.sep);

/** The text of `file` with no newline at its end. */
const textOf = async (file: string): Promise<string> =>
  (await Bun.file(file).text()).replace(/\n+$/, "");

/** `text` with each include and value of the source `source` filled in from `shared`. */
async function fill(
  text: string,
  shared: string,
  source: string,
): Promise<string> {
  const names = [...text.matchAll(INCLUDE)].map((m) => m[1] as string);
  const parts: Record<string, string> = {};
  for (const name of names) {
    const file = path.join(
      shared,
      name.endsWith(".json") ? name : `${name}.md`,
    );
    if (!fs.existsSync(file))
      throw new Error(
        `${source}: no shared part ${posix(path.relative(path.dirname(shared), file))}`,
      );
    parts[name] = await textOf(file);
  }
  const included = text.replace(
    INCLUDE,
    (_m, name: string) => parts[name] as string,
  );
  return included.replace(VALUE, (_m, name: string) => {
    if (!(name in VALUES)) throw new Error(`${source}: no value {{${name}}}`);
    return VALUES[name] as string;
  });
}

/** `text` with the header that names `source`, in the comment form of the file type. */
export function withHeader(file: string, source: string, text: string): string {
  const line = `${GENERATED_MARK} \`${source}\`. Edit the source and run \`just generate\`.`;
  if (file.endsWith(".ts")) return `// ${line}\n${text}`;
  if (!file.endsWith(".md")) return text;
  // A frontmatter starts the file, so the header goes inside it as a YAML comment.
  if (text.startsWith("---\n")) return `---\n# ${line}\n${text.slice(4)}`;
  return `<!-- ${line} -->\n\n${text}`;
}

/** The text of a `hooks.json` file for `json`, with a one-item `modules` list on one line. */
export const formatHooks = (json: HooksFile): string =>
  `${JSON.stringify(json, null, 2).replace(/"modules": \[\n\s+("[^"]+")\n\s+\]/, '"modules": [$1]')}\n`;

/** The `hooks.json` object of the source folder `dir`, with the texts of its text files. */
export async function withTexts(dir: string, text: string): Promise<HooksFile> {
  const json = JSON.parse(text) as HooksFile;
  for (const name of fs.readdirSync(dir).sort()) {
    const file = path.join(dir, name);
    if (name === "description.txt") {
      json.description = (await textOf(file)).split("\n").join(" ");
      continue;
    }
    const event = name.match(PROMPT_FILE)?.[1];
    if (!event) continue;
    const prompts = (json.hooks?.[event] ?? [])
      .flatMap((group) => group.hooks)
      .filter((hook) => hook.type === "prompt");
    const [prompt] = prompts;
    if (prompts.length !== 1 || !prompt)
      throw new Error(
        `${file}: ${event} has ${prompts.length} prompt hooks, and the file needs exactly one`,
      );
    prompt.prompt = await textOf(file);
  }
  return json;
}

/** Each file under `dir`, relative to `dir`, with `/` separators, sorted. */
const walk = (dir: string): string[] =>
  fs.existsSync(dir)
    ? fs
        .readdirSync(dir, { recursive: true, withFileTypes: true })
        .filter((e) => e.isFile())
        .map((e) => posix(path.relative(dir, path.join(e.parentPath, e.name))))
        .sort()
    : [];

/** True when the source file `rel` is a text input of a `hooks.json`, and gives no file of its own. */
const isHookText = (rel: string): boolean =>
  /(?:^|\/)hooks\/(?:description\.txt|[A-Za-z]+\.prompt\.txt)$/.test(rel);

/** The module path and the constant name of a text of a module folder, such as `a/texts.ts/doing-tasks.md`. */
const MODULE_TEXT = /^(.+\.ts)\/([a-z0-9-]+)\.(?:md|json)$/;

/** `text` as a template literal that gives the same string. */
const literal = (text: string): string =>
  `\`${text.replace(/[\\`]/g, "\\$&").replace(/\$\{/g, "\\${")}\``;

/** The text module of the source folder `dir` of `root`: one constant for each `.md` or `.json` file, in name order. */
async function textModule(
  src: string,
  shared: string,
  dir: string,
): Promise<string> {
  const lines: string[] = [];
  for (const name of fs.readdirSync(path.join(src, dir)).sort()) {
    const source = path.posix.join("src", dir, name);
    const [, base, ext] = name.match(/^([a-z0-9-]+)\.(md|json)$/) ?? [];
    if (!base)
      throw new Error(
        `${source}: a module folder holds only \`.md\` and \`.json\` files`,
      );
    const text = (
      await fill(
        await Bun.file(path.join(src, dir, name)).text(),
        shared,
        source,
      )
    ).replace(/\n+$/, "");
    if (ext === "json") {
      try {
        JSON.parse(text);
      } catch (err) {
        throw new Error(`${source}: ${(err as Error).message}`);
      }
    }
    lines.push(
      `/** From \`${name}\`. */`,
      `export const ${base.toUpperCase().replace(/-/g, "_")} = ${ext === "json" ? text : literal(text)};`,
      "",
    );
  }
  return format(path.join(dir), lines.join("\n"));
}

/** `text` as Biome formats the module `file`. */
async function format(file: string, text: string): Promise<string> {
  const run = Bun.spawn(
    ["bunx", "biome", "format", `--stdin-file-path=${file}`],
    { cwd: REPO, stdin: new Blob([text]), stdout: "pipe", stderr: "pipe" },
  );
  const [out, err, code] = await Promise.all([
    new Response(run.stdout).text(),
    new Response(run.stderr).text(),
    run.exited,
  ]);
  if (code !== 0) throw new Error(`biome format ${file}: ${err}`);
  return out;
}

/** The generated files of the repository `root`, from its `src/` folder. */
export async function outputs(root: string): Promise<Output[]> {
  const src = path.join(root, "src");
  const shared = path.join(src, "shared");
  const out: Output[] = [];
  const modules = new Set<string>();
  for (const rel of walk(src)) {
    if (rel.startsWith("shared/") || isHookText(rel)) continue;
    const module = rel.match(MODULE_TEXT)?.[1];
    if (module) {
      if (modules.has(module)) continue;
      modules.add(module);
      const source = `src/${module}/`;
      out.push({
        file: module,
        source,
        text: withHeader(module, source, await textModule(src, shared, module)),
      });
      continue;
    }
    const source = `src/${rel}`;
    const from = path.join(src, rel);
    let text = await fill(await Bun.file(from).text(), shared, source);
    if (path.basename(rel) === "hooks.json")
      text = formatHooks(await withTexts(path.dirname(from), text));
    out.push({ file: rel, source, text: withHeader(rel, source, text) });
  }
  return out;
}

/** The generated files under `plugins/` and `wiki/` of `root` that have no source any more. */
export async function orphans(root: string, made: Output[]): Promise<string[]> {
  const known = new Set(made.map((o) => o.file));
  const found: string[] = [];
  for (const top of ["plugins", "wiki"])
    for (const rel of walk(path.join(root, top))) {
      const file = `${top}/${rel}`;
      if (known.has(file) || !/\.(?:md|ts)$/.test(file)) continue;
      if (isGenerated(await Bun.file(path.join(root, file)).text()))
        found.push(file);
    }
  return found;
}

/** The messages for each generated file of `root` that differs from its source, or that has no source. */
export async function stale(root: string): Promise<string[]> {
  const made = await outputs(root);
  const found: string[] = [];
  for (const o of made) {
    const at = path.join(root, o.file);
    const now = fs.existsSync(at) ? await Bun.file(at).text() : null;
    if (now !== o.text)
      found.push(
        `${o.file} differs from its source ${o.source}. Edit the source and run \`just generate\`.`,
      );
  }
  for (const file of await orphans(root, made))
    found.push(
      `${file} has the header of a generated file, but no source in src/.`,
    );
  return found;
}

if (process.argv[1] === import.meta.path) {
  if (process.argv.includes("--check")) {
    const found = await stale(REPO);
    for (const line of found) console.error(line);
    process.exit(found.length ? 1 : 0);
  }
  for (const o of await outputs(REPO)) {
    const at = path.join(REPO, o.file);
    if (fs.existsSync(at) && (await Bun.file(at).text()) === o.text) continue;
    fs.mkdirSync(path.dirname(at), { recursive: true });
    await Bun.write(at, o.text);
    console.log(`Wrote ${o.file}`);
  }
}
